CREATE POLICY "own assets insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'video-assets' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "own assets update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'video-assets' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "own assets delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'video-assets' AND (storage.foldername(name))[1] = auth.uid()::text);